- New console entries: ../../../.local/share/omgithub-playwright/output/console-2026-10-31T13-52-12-893Z.log#L28
"PASS: got attic_key
PASS: watch combined
PASS: in attic
PASS: candle lit
PASS: has rope
PASS: has master_key
PASS: good ending panel shown
PASS: ending TRUE ESCAPE"
await page.evaluate('
async ()=>{
  const g=window.MYSTERY_HOUSE.game; const MH=window.MYSTERY_HOUSE;
  const res=[]; const ck=(n,c)=>res.push((c?'PASS':'FAIL')+': '+n);
  const canvas=document.getElementById('gameCanvas');
  const {width:dW,height:dH}=canvas.getBoundingClientRect();
  const scale=Math.min(dW/960,dH/640);
  const offX=(dW-960*scale)/2, offY=(dH-640*scale)/2;
  function clickCanvas(lx,ly){canvas.dispatchEvent(new MouseEvent('mousedown',{bubbles:true,cancelable:true,clientX:offX+lx*scale,clientY:offY+ly*scale}));}
  function dismiss(){const ok=document.getElementById('btn-message-ok'); const p=ok.closest('.panel'); if(!p.classList.contains('hidden')) ok.click();}
  clickCanvas(410,475); dismiss();          // rusty key
  g.go('library');
  clickCanvas(410,300); dismiss();          // iron key
  g.go('study');
  clickCanvas(710,280);                     // safe overlay
  const sd2=g.safeDial; sd2[0]=4; sd2[1]=1; sd2[2]=7;
  document.getElementById('safe-open').click(); dismiss();
  ck('got attic_key', g.hasItem('attic_key'));
  clickCanvas(330,410); dismiss();          // candle + matchbox
  g.go('dining');
  clickCanvas(410,270); dismiss();          // broken_watch
  clickCanvas(160,440); dismiss();          // watch_battery
  MH.attemptCombine('broken_watch','watch_battery');
  ck('watch combined', g.hasItem('watch'));
  g.go('attic');                            // unlock + enter
  ck('in attic', g.room==='attic');
  MH.attemptCombine('candle','matchbox');
  ck('candle lit', g.flags.candleLit===true);
  clickCanvas(670,390); dismiss();          // trunk rope+master_key
  ck('has rope', g.hasItem('rope'));
  ck('has master_key', g.hasItem('master_key'));
  clickCanvas(800,250);                     // window -> good ending
  await new Promise(r=>setTimeout(r,200));
  const ep=document.getElementById('panel-ending');
  ck('good ending panel shown', ep && !ep.classList.contains('hidden'));
  ck('ending TRUE ESCAPE', document.getElementById('ending-title').textContent==='TRUE ESCAPE');
  return res.join('\n');
}
');

