cd /home/runner/work/PlayGround/PlayGround && echo "=== HINT + WRONG SAFE COMBO ===" && playwright-cli -s=mh eval "
async ()=>{
  const g=window.MYSTERY_HOUSE.game; const res=[]; const ck=(n,c)=>res.push((c?'PASS':'FAIL')+': '+n);
  // hint panel
  document.getElementById('btn-hint').click();
  const hp=document.getElementById('panel-hint');
  ck('hint panel shown', hp && !hp.classList.contains('hidden'));
  ck('hint has text', document.getElementById('panel-hint-text').textContent.length>0);
  document.getElementById('btn-hint-close').click();
  ck('hint closed', document.getElementById('panel-hint').classList.contains('hidden'));
  // wrong safe combo
  g.go('study');
  const canvas=document.getElementById('gameCanvas');
  const {width:dW,height:dH}=canvas.getBoundingClientRect(); const scale=Math.min(dW/960,dH/640);
  const offX=(dW-960*scale)/2, offY=(dH-640*scale)/2;
  canvas.dispatchEvent(new MouseEvent('mousedown',{bubbles:true,cancelable:true,clientX:offX+710*scale,clientY:offY+280*scale}));
  const sd=g.safeDial; sd[0]=9; sd[1]=9; sd[2]=9;
  document.getElementById('safe-open').click();
  await new Promise(r=>setTimeout(r,100));
  ck('safe NOT opened on wrong combo', !g.flags.safeOpened);
  document.getElementById('btn-message-ok').click();
  document.getElementById('safe-close').click();
  return res.join('\\n');
}
" 2>&1 | grep -E 'PASS|FAIL|Error|TypeError'

